import path from 'path';

const JS_EXTENSIONS = ['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs', '.mts', '.cts'];
const PYTHON_EXTENSIONS = ['.py'];
const NOTEBOOK_EXTENSIONS = ['.ipynb'];
const R_EXTENSIONS = ['.r', '.rmd'];
const JVM_EXTENSIONS = ['.java', '.scala'];

// Replaces every regex match with blank lines so later matches can't span a removed comment.
const blankOut = (text) => text.replace(/[^\n]/g, ' ');

// Removes // and /* */ comments while leaving string and template literals intact.
const stripCStyleComments = (content) =>
  content.replace(
    /("(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'|`(?:\\.|[^`\\])*`)|\/\*[\s\S]*?\*\/|\/\/[^\n]*/g,
    (match, literal) => literal ?? blankOut(match)
  );

// Removes # comments and triple-quoted strings (docstrings) while leaving other strings intact.
const stripHashComments = (content) =>
  content.replace(
    /("""[\s\S]*?"""|'''[\s\S]*?''')|("(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*')|#[^\n]*/g,
    (match, docstring, literal) => literal ?? blankOut(match)
  );

const collect = (content, pattern, group, into) => {
  for (const match of content.matchAll(pattern)) {
    const specifier = match[group]?.trim();
    if (specifier) into.push(specifier);
  }
  return into;
};

export function extractJsImports(content) {
  const code = stripCStyleComments(content);
  const specifiers = [];
  // import x from '…', import type { X } from '…', import { a,\n b } from '…', export * from '…'
  collect(
    code,
    /(?<![\w$.])(?:import|export)(?:\s+type)?\s+[^'"`;]*?\bfrom\s*(['"])([^'"\n]+)\1/g,
    2,
    specifiers
  );
  // import '…'
  collect(code, /(?<![\w$.])import\s*(['"])([^'"\n]+)\1/g, 2, specifiers);
  // require('…'), import('…')
  collect(code, /(?<![\w$.])(?:require|import)\s*\(\s*(['"`])([^'"`\n]+)\1\s*[,)]/g, 2, specifiers);
  return specifiers;
}

export function extractPythonImports(content) {
  const code = stripHashComments(content).replace(/\\\r?\n/g, ' ');
  const specifiers = [];
  for (const line of code.split(/\r?\n/)) {
    for (const statement of line.split(';')) {
      const fromMatch = statement.match(/^\s*from\s+([\w.]+)\s+import\b/);
      if (fromMatch) {
        specifiers.push(fromMatch[1]);
        continue;
      }
      const importMatch = statement.match(/^\s*import\s+(.+)$/);
      if (importMatch) {
        for (const item of importMatch[1].split(',')) {
          const name = item.trim().split(/\s+as\s+/)[0].trim();
          if (/^[A-Za-z_][\w.]*$/.test(name)) specifiers.push(name);
        }
      }
    }
  }
  // importlib.import_module('…'), __import__('…')
  collect(code, /(?<![\w.])(?:import_module|__import__)\s*\(\s*(['"])([\w.]+)\1/g, 2, specifiers);
  return specifiers;
}

export function extractNotebookImports(content) {
  let notebook;
  try {
    notebook = JSON.parse(content);
  } catch {
    return extractPythonImports(content);
  }
  const cells = Array.isArray(notebook?.cells) ? notebook.cells : [];
  const source = cells
    .filter((cell) => cell?.cell_type === 'code')
    .map((cell) => (Array.isArray(cell.source) ? cell.source.join('') : String(cell.source ?? '')))
    .join('\n');
  return extractPythonImports(source);
}

export function extractRImports(content) {
  const code = stripHashComments(content);
  const specifiers = [];
  collect(code, /(?<![\w.])(?:library|require|requireNamespace)\s*\(\s*(['"]?)([A-Za-z][\w.]*)\1/g, 2, specifiers);
  collect(code, /(?<![\w.])([A-Za-z][\w.]*):::?/g, 1, specifiers);
  return specifiers;
}

export function extractJvmImports(content) {
  const code = stripCStyleComments(content);
  return collect(code, /^\s*import\s+(?:static\s+)?([\w.]+)/gm, 1, []);

